import React from "react";

const SummaryCards = ({ transactions }) => {
  const total = transactions.reduce((acc, t) => acc + Number(t.amount), 0);

  return (
    <div style={{ marginBottom: "20px" }}>
      <h3>Total Balance: ₹{total}</h3>
    </div>
  );
};

export default SummaryCards;
